import{z as D,x as A,o as r,c as B,q as o,j as l,D as e,d as E,s as i,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"SPF / DKIM / DMARC","description":"","frontmatter":{"title":"SPF / DKIM / DMARC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spf-dkim-dmarc.md","filePath":"cs/spf-dkim-dmarc.md","lastUpdated":1791063341000}'),p={name:"cs/spf-dkim-dmarc.md"};function d(m,a,F,C,c,M){const t=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=o('<h1 id="spf-dkim-dmarc" tabindex="-1">SPF / DKIM / DMARC <a class="header-anchor" href="#spf-dkim-dmarc" aria-label="Permalink to &quot;SPF / DKIM / DMARC&quot;">​</a></h1><div class="epigraph"><p>SPF 授权哪些 IP 能用你的域发信，DKIM 签报头与正文，DMARC 告诉接收方失败时拒还是隔离，并要报告。</p><footer>—— 据 RFC 7208 SPF；RFC 6376 DKIM；RFC 7489 DMARC 整理</footer></div><p><a href="/cs/smtp-imap">SMTP</a> 默认信 MAIL FROM，<a href="/cs/dns">DNS</a> 能放策略记录，<a href="/cs/smtp-imap">上一课</a> 留下伪造缺口。缺口是<strong>域认证三件套</strong>。本课不把 SSH 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任何人可对 25 端口说 <code>MAIL FROM: you@bank</code>，SMTP 本身不验。三件套各补一层：SPF 是 IP 授权——域主在 DNS TXT 里列合法发送主机，收信方查连接 IP 是否在列，它挂在信封 MAIL FROM 域上，邮件一被转发就破，因为转发者 IP 不在原域清单里。DKIM 是内容签名——私钥签报头与正文，公钥在 DNS，验证不依赖传输路径，转发后仍可验，除非中间改了正文。DMARC 是政策层——要求通过的域与可见的 From 头对齐，失败时按 p=none/quarantine/reject 处置，并要求 rua 报告。与 DNSSEC/RPKI 同构：都是用既有基础设施钉住「源是谁」。不要把三件套写成端到端加密：路由上的服务器照样读信。</p><p><span class="marginnote">RFC 7489。对齐 relaxed/strict。本课不写垃圾分类器特征。</span></p><p><span class="marginnote">常见误区：把三件套当成端到端加密。实际上它们只回答「这封信是不是你域里发出来的」，中转服务器仍能完整读正文——要机密得另外上 S/MIME 或 PGP。</span></p><h3 id="钉域不是加密邮件" tabindex="-1">钉域不是加密邮件 <a class="header-anchor" href="#钉域不是加密邮件" aria-label="Permalink to &quot;钉域不是加密邮件&quot;">​</a></h3><p>分工一句话：SPF 钉发送路径，转发会破；DKIM 签体；DMARC 给政策。三者与 RPKI 同属源认证，与加密无关。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程走一遍：发出端 DKIM 签名，接收端先查 SPF 再验 DKIM，最后按 From 域的 DMARC 记录决策，聚合报告经 rua 回流域主。对照 Cookie：都是把身份关联到请求——一层绑邮件域，一层绑 Web 会话，失败模式也同型：伪造声明或劫持既有信任。</p>',11)),(r(),l(n,null,{default:e(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPF%5B%22SPF%20%E6%8E%88%E6%9D%83%20IP%22%5D%20--%3E%20DEC%5B%22DMARC%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20DKIM%5B%22DKIM%20%E7%AD%BE%E5%90%8D%22%5D%20--%3E%20DEC%0A%20%20DEC%20--%3E%20POL%5B%22none%2Fquarantine%2Freject%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[E("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"运营四个坑。GeoDNS 别把 MX 指向不在 SPF 里的出口 IP，自相矛盾直接掉进隔离。转发要靠 SRS 重写信封或 ARC 传递既有验证结论（点名）。DKIM 记录 TTL 太长则密钥轮换慢，泄露后撤不干净。DoH 加密查询，但不改这些 TXT 的语义，挡不住策略本身配错。失败报告帮域主发现劫持滥发，也携带收件元数据——可见性与隐私之间的运营权衡。",-1)),(r(),l(n,null,{default:e(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%94%B6%E5%88%B0%E9%82%AE%E4%BB%B6%22%5D%20--%3E%20B%7B%22%E8%BF%9E%E6%8E%A5%20IP%20%E5%9C%A8%20SPF%20%E6%B8%85%E5%8D%95%E9%87%8C%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20F1%5B%22SPF%20fail%20%E8%AE%B0%E4%B8%BA%E8%BD%AF%E5%A4%B1%E8%B4%A5%E5%80%99%E9%80%89%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%7B%22DKIM%20%E7%AD%BE%E5%90%8D%E9%AA%8C%E5%BE%97%E8%BF%87%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E5%90%A6%22%7C%20F2%5B%22DKIM%20fail%20%E8%AE%B0%E4%B8%BA%E5%80%99%E9%80%89%22%5D%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20D%7B%22%E9%80%9A%E8%BF%87%E5%9F%9F%E4%B8%8E%20From%20%E5%A4%B4%E5%AF%B9%E9%BD%90%EF%BC%9F%22%7D%0A%20%20F1%20--%3E%20D%0A%20%20F2%20--%3E%20D%0A%20%20D%20--%3E%7C%22%E5%AF%B9%E9%BD%90%E4%B8%94%E8%87%B3%E5%B0%91%E4%B8%80%E9%A1%B9%E9%80%9A%E8%BF%87%22%7C%20E%5B%22DMARC%20pass%20%E6%AD%A3%E5%B8%B8%E6%8A%95%E9%80%92%22%5D%0A%20%20D%20--%3E%7C%22%E6%9C%AA%E5%AF%B9%E9%BD%90%22%7C%20G%5B%22%E6%9F%A5%20p%3D%20%E7%AD%96%E7%95%A5%3A%20none%2Fquarantine%2Freject%22%5D%0A%20%20G%20--%3E%20H%5B%22%E6%B1%87%E6%80%BB%E5%86%99%E8%BF%9B%20rua%20%E8%81%9A%E5%90%88%E6%8A%A5%E5%91%8A%E5%9B%9E%E6%B5%81%E5%9F%9F%E4%B8%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">SRS 就是转发服务器把信封 MAIL FROM 改写成自己域下的地址（如 <a href="mailto:srs0+hash@forwarder.com" target="_blank" rel="noreferrer">srs0+hash@forwarder.com</a>），让 SPF 检查落到自己头上——相当于代寄人重新签收，信封换名、信纸不动。</span></p><p><span class="marginnote">数字实例：DKIM 记录 TTL 设 86400 秒（一天）时，私钥泄露后旧公钥最长还要在 DNS 里挂一天，攻击者有约一天的窗口能伪造你域的签名信；做密钥轮换时把 TTL 压到 600 秒可把窗口缩到十分钟。</span></p><p><span class="marginnote">「对齐」怎么算：From 是 <a href="mailto:news@mail.example.com" target="_blank" rel="noreferrer">news@mail.example.com</a>，MAIL FROM 是 mail.example.com，relaxed 模式下取组织域 example.com 相等即算对齐——所以子域发信能过。初学者容易以为要求逐字符相同，那是 strict 模式。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BIMI 的全部；SSH 协议是下一课。后课默认：邮件域认证靠 SPF+DKIM+DMARC，提供源认证不提供机密。组合经验一条：只开 SPF 不开 DKIM，转发场景脆弱；只开 DKIM 不开 DMARC，接收方无政策可执行。</p><p>下一课<a href="/cs/ssh-protocol">SSH 协议</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SPF 钉 IP，DKIM 钉内容，DMARC 钉政策。</li><li>转发是 SPF 的经典裂缝。</li><li>与 DNSSEC/RPKI 同属源认证。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 7208；RFC 6376；RFC 7489。</li></ul>',8))])}const h=D(p,[["render",d]]);export{P as __pageData,h as default};
